import React, { useEffect, useState } from "react";
import API from "../api";

export default function Dashboard({ token, onLogout }) {
  const [data, setData] = useState("");
  const [user, setUser] = useState("");

  useEffect(() => {
    const load = async () => {
      try {
        const res = await API.get("/auth/profile", {
          headers: { Authorization: `Bearer ${token}` }
        });
        setData(res.data.msg);
        setUser(res.data.user.username);
      } catch (err) {
        setData("Ошибка доступа");
      }
    };

    load();
  }, [token]);

  return (
    <section className="dashboard">
      <header>
        <div>
          <h1>Панель управления</h1>
          <p>{user ? `Пользователь: ${user}` : "Проверка доступа..."}</p>
        </div>
        <button className="secondary" onClick={onLogout}>Выйти</button>
      </header>

      <div className="grid">
        <article>
          <h2>Статус API</h2>
          <p>{data}</p>
        </article>
        <article>
          <h2>Авторизация</h2>
          <p>JWT-токен сохранен в браузере и используется для защищенных запросов.</p>
        </article>
        <article>
          <h2>База данных</h2>
          <p>Пользователи хранятся в MongoDB, пароли защищены bcrypt-хешированием.</p>
        </article>
      </div>
    </section>
  );
}
